const body = $('استقبال الطلب').first().json.body ?? {};
const _raw = $input.first().json ?? {};
const ext = (_raw.output && typeof _raw.output === 'object') ? _raw.output : _raw;
const zone = 'Asia/Riyadh';

// معرّف المستخدم يأتي من جلسة الخادم في Next.js ولا يُقبل من المتصفح أبداً
const userId = String(body.user_id ?? '').trim();
if (!userId) throw new Error('جلستك انتهت. سجّل دخولك مرة أخرى');

if (ext.is_transaction === false) {
  throw new Error('هذي الجملة ما فيها حركة مالية. اذكر المبلغ والجهة، مثل: صرفت 20 ريال عند المصنع');
}

let amount = Number(ext.amount);
if (!Number.isFinite(amount) || amount <= 0) {
  throw new Error('ما قدرت أفهم المبلغ من الجملة. جرّب صيغة مثل: صرفت 20 ريال عند المصنع');
}
amount = Math.round(amount * 100) / 100;

let spent = DateTime.fromISO(String(ext.spent_at ?? ''), { zone });
if (!spent.isValid) spent = DateTime.now().setZone(zone);

const allowed = ['مطاعم', 'بقالة', 'قهوة', 'بنزين', 'نقل', 'فواتير', 'إيجار', 'اشتراكات', 'صحة', 'تعليم', 'ترفيه', 'ملابس', 'هدايا', 'ضيافة', 'صيانة', 'رسوم', 'مواد خام', 'راتب', 'مبيعات', 'أخرى'];
const category = allowed.includes(ext.category) ? ext.category : 'أخرى';

return [{
  json: {
    user_id: userId,
    spent_at: spent.startOf('day').toISO(),
    amount,
    vat_amount: 0,
    currency: String(ext.currency || 'SAR').toUpperCase().slice(0, 3),
    direction: ext.direction === 'income' ? 'income' : 'expense',
    category,
    vendor: String(ext.vendor ?? '').trim(),
    tax_number: '',
    invoice_number: '',
    note: String(ext.note ?? '').trim(),
    raw_text: String(body.text ?? '').trim(),
    source: 'text',
    receipt_url: '',
    receipt_file_id: '',
    deleted: false,
    delete_reason: '',
  },
}];

const body = $('استقبال الطلب').first().json.body ?? {};
const zone = 'Asia/Riyadh';

const userId = String(body.user_id ?? '').trim();
if (!userId) throw new Error('جلستك انتهت. سجّل دخولك مرة أخرى');

let b64 = String(body.imageBase64 ?? '').trim();
if (!b64) throw new Error('ما وصلت أي صورة. اختر صورة الفاتورة وحاول مرة أخرى');

// الواجهة قد ترسل data URL كاملاً — نستخرج النوع والبيانات منه
let mime = String(body.mimeType ?? '').trim();
const m = b64.match(/^data:([^;]+);base64,(.*)$/s);
if (m) { mime = mime || m[1]; b64 = m[2]; }
b64 = b64.replace(/\s/g, '');

const okTypes = ['image/jpeg', 'image/png', 'image/webp', 'image/gif'];
if (!okTypes.includes(mime)) {
  throw new Error('نوع الصورة غير مدعوم. استخدم JPG أو PNG');
}

// الطول بالبايت ≈ ثلاثة أرباع طول نص base64
const bytes = Math.floor((b64.length * 3) / 4);
if (bytes > 5 * 1024 * 1024) throw new Error('الصورة كبيرة جداً. صغّرها وحاول مرة أخرى');
if (bytes < 1024) throw new Error('الصورة تالفة أو فارغة');

const today = DateTime.now().setZone(zone).toISODate();

const schema = {
  type: 'object',
  properties: {
    is_receipt: { type: 'boolean', description: 'true فقط إذا كانت الصورة فاتورة أو إيصال شراء أو سند قبض فيه مبلغ واضح. false لأي صورة أخرى مثل صورة شخصية أو منظر أو لقطة شاشة لا تحتوي فاتورة.' },
    total: { type: 'number', description: 'الإجمالي النهائي المدفوع شاملاً الضريبة، رقماً فقط. إذا لم يظهر إجمالي واضح ضع 0.' },
    vat: { type: 'number', description: 'مبلغ ضريبة القيمة المضافة كما هو مكتوب في الفاتورة. ضع 0 إذا لم تُذكر صراحةً. لا تحسبها بنفسك.' },
    currency: { type: 'string', description: 'رمز العملة ISO. ريال أو SAR أو ر.س = SAR. إذا لم تظهر عملة استخدم SAR.' },
    direction: { type: 'string', enum: ['expense', 'income'], description: 'expense لفاتورة شراء أو مصروف. income لسند قبض أو فاتورة مبيعات صادرة منك.' },
    vendor: { type: 'string', description: 'اسم المتجر أو المورد كما هو مكتوب في الفاتورة. فارغ إذا لم يظهر.' },
    tax_number: { type: 'string', description: 'الرقم الضريبي للمنشأة، عادةً 15 رقماً. فارغ إذا لم يظهر. لا تخترعه.' },
    invoice_number: { type: 'string', description: 'رقم الفاتورة أو الإيصال كما هو مكتوب. فارغ إذا لم يظهر.' },
    date: { type: 'string', description: 'تاريخ الفاتورة بصيغة YYYY-MM-DD. إذا لم يظهر تاريخ استخدم ' + today + ' حرفياً.' },
    category: { type: 'string', enum: ['مطاعم', 'بقالة', 'قهوة', 'بنزين', 'نقل', 'فواتير', 'إيجار', 'اشتراكات', 'صحة', 'تعليم', 'ترفيه', 'ملابس', 'هدايا', 'ضيافة', 'صيانة', 'رسوم', 'مواد خام', 'راتب', 'مبيعات', 'أخرى'], description: 'أقرب تصنيف لمحتوى الفاتورة. إذا لم يتضح اختر أخرى.' },
    summary: { type: 'string', description: 'وصف مختصر جداً لأهم ما اشتُري، بالعربي، في أربع كلمات أو أقل.' },
  },
  required: ['is_receipt', 'total', 'direction', 'date', 'category'],
};

const payload = {
  model: 'claude-haiku-4-5-20251001',
  max_tokens: 1024,
  temperature: 0,
  tools: [{ name: 'record_invoice', description: 'تسجيل بيانات الفاتورة المستخرجة من الصورة', input_schema: schema }],
  tool_choice: { type: 'tool', name: 'record_invoice' },
  messages: [{
    role: 'user',
    content: [
      { type: 'image', source: { type: 'base64', media_type: mime, data: b64 } },
      { type: 'text', text: 'اليوم هو ' + today + ' بتوقيت الرياض. اقرأ هذه الفاتورة واستخرج بياناتها. لا تخترع أي رقم غير مكتوب في الصورة.' },
    ],
  }],
};

return [{ json: { payload, mime, b64, bytes } }];

const zone = 'Asia/Riyadh';
const res = $input.first().json ?? {};
const prep = $('تجهيز طلب الرؤية').first().json ?? {};

// عند إجبار الأداة، تأتي المخرجات داخل كتلة tool_use
const block = (res.content || []).find((c) => c && c.type === 'tool_use');
const ext = (block && block.input) || {};

if (ext.is_receipt === false) {
  throw new Error('هذي الصورة ما تبيّن أنها فاتورة. صوّر الفاتورة كاملة وواضحة وحاول مرة أخرى');
}

let amount = Number(ext.total);
if (!Number.isFinite(amount) || amount <= 0) {
  throw new Error('ما قدرت أقرأ الإجمالي من الفاتورة. صوّرها بإضاءة أوضح، أو سجّلها يدوياً بالكتابة');
}
amount = Math.round(amount * 100) / 100;

let vat = Number(ext.vat);
if (!Number.isFinite(vat) || vat < 0 || vat > amount) vat = 0;
vat = Math.round(vat * 100) / 100;

let spent = DateTime.fromISO(String(ext.date ?? ''), { zone });
if (!spent.isValid) spent = DateTime.now().setZone(zone);
// فاتورة بتاريخ مستقبلي أو قديم جداً تعني قراءة خاطئة — نرجع لليوم
const now = DateTime.now().setZone(zone);
if (spent > now.plus({ days: 1 }) || spent < now.minus({ years: 5 })) spent = now;

const allowed = ['مطاعم', 'بقالة', 'قهوة', 'بنزين', 'نقل', 'فواتير', 'إيجار', 'اشتراكات', 'صحة', 'تعليم', 'ترفيه', 'ملابس', 'هدايا', 'ضيافة', 'صيانة', 'رسوم', 'مواد خام', 'راتب', 'مبيعات', 'أخرى'];
const category = allowed.includes(ext.category) ? ext.category : 'أخرى';

const vendor = String(ext.vendor ?? '').trim();
const stamp = DateTime.now().setZone(zone).toFormat('yyyy-MM-dd_HHmmss');
const safeVendor = (vendor || 'فاتورة').replace(/[\\/:*?"<>|]/g, '').slice(0, 40);
const extMap = { 'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp', 'image/gif': 'gif' };
const fileExtension = extMap[prep.mime] || 'jpg';
const fileName = stamp + '_' + safeVendor + '_' + amount + '.' + fileExtension;

return [{
  json: {
    spent_at: spent.startOf('day').toISO(),
    amount,
    vat_amount: vat,
    currency: String(ext.currency || 'SAR').toUpperCase().slice(0, 3),
    direction: ext.direction === 'income' ? 'income' : 'expense',
    category,
    vendor,
    tax_number: String(ext.tax_number ?? '').trim(),
    invoice_number: String(ext.invoice_number ?? '').trim(),
    note: String(ext.summary ?? '').trim(),
    file_name: fileName,
  },
  binary: {
    data: {
      data: prep.b64,
      mimeType: prep.mime,
      fileName,
      fileExtension,
    },
  },
}];

const rec = $('قراءة نتيجة الفاتورة').first().json ?? {};
const drive = $input.first().json ?? {};

// رفع الصورة ليس شرطاً لحفظ الحركة: لو فشل درايف نسجّل البيانات ونخبر المستخدم
const fileId = String(drive.id ?? '').trim();
// نبني الرابط من المعرّف بدل الاعتماد على حقل قد لا يرجعه درايف
const url = fileId ? ('https://drive.google.com/file/d/' + fileId + '/view') : '';

return [{
  json: {
    user_id: String($('استقبال الطلب').first().json.body.user_id ?? '').trim(),
    receipt_saved: Boolean(fileId),
    spent_at: rec.spent_at,
    amount: rec.amount,
    vat_amount: rec.vat_amount,
    currency: rec.currency,
    direction: rec.direction,
    category: rec.category,
    vendor: rec.vendor,
    tax_number: rec.tax_number,
    invoice_number: rec.invoice_number,
    note: rec.note,
    raw_text: 'فاتورة: ' + (rec.vendor || 'بلا اسم') + (rec.invoice_number ? (' — رقم ' + rec.invoice_number) : ''),
    source: 'receipt',
    receipt_url: url,
    receipt_file_id: fileId,
    deleted: false,
    delete_reason: '',
  },
}];

const zone = 'Asia/Riyadh';
const body = $('استقبال الطلب').first().json.body ?? {};
const now = DateTime.now().setZone(zone);
const todayKey = now.toISODate();
const round = (n) => Math.round(n * 100) / 100;

// الشهر المطلوب، أو الشهر الجاري افتراضياً
const asked = String(body.month ?? '');
const month = /^\d{4}-\d{2}$/.test(asked) ? asked : now.toFormat('yyyy-MM');
const prevMonth = DateTime.fromISO(month + '-01', { zone }).minus({ months: 1 }).toFormat('yyyy-MM');

const rows = $input.all().map((i) => i.json).filter((r) => r && r.id !== undefined && r.id !== null);

const mapRow = (r) => {
  const d = DateTime.fromISO(String(r.spent_at ?? ''), { zone });
  return {
    id: r.id,
    spent_at: d.isValid ? d.toISODate() : null,
    amount: Number(r.amount) || 0,
    vat_amount: Number(r.vat_amount) || 0,
    currency: r.currency || 'SAR',
    direction: r.direction === 'income' ? 'income' : 'expense',
    category: r.category || 'أخرى',
    vendor: r.vendor || '',
    tax_number: r.tax_number || '',
    invoice_number: r.invoice_number || '',
    note: r.note || '',
    raw_text: r.raw_text || '',
    source: r.source || 'text',
    receipt_url: r.receipt_url || '',
    deleted: r.deleted === true,
    deleted_at: r.deleted_at || null,
    delete_reason: r.delete_reason || '',
    edited_at: r.edited_at || null,
    created_at: r.createdAt || null,
  };
};

const byNewest = (a, b) => String(b.spent_at).localeCompare(String(a.spent_at)) || Number(b.id) - Number(a.id);
const all = rows.map(mapRow);
const live = all.filter((e) => !e.deleted);

const inMonth = (e, m) => typeof e.spent_at === 'string' && e.spent_at.startsWith(m);
const isExp = (e) => e.direction === 'expense';
const sum = (list) => round(list.reduce((s, e) => s + e.amount, 0));

const statsFor = (m) => {
  const rowsM = live.filter((e) => inMonth(e, m));
  const expense = sum(rowsM.filter(isExp));
  const income = sum(rowsM.filter((e) => !isExp(e)));
  return { expense, income, net: round(income - expense), count: rowsM.length };
};

const cur = statsFor(month);
const prev = statsFor(prevMonth);

const pct = (a, b) => (b === 0 ? null : round(((a - b) / b) * 100));

// الرصيد الجاري: كل الحركات الحيّة حتى نهاية الشهر المعروض
const monthEnd = DateTime.fromISO(month + '-01', { zone }).endOf('month').toISODate();
const upTo = live.filter((e) => typeof e.spent_at === 'string' && e.spent_at <= monthEnd);
const balance = round(sum(upTo.filter((e) => !isExp(e))) - sum(upTo.filter(isExp)));

const monthRows = live.filter((e) => inMonth(e, month)).sort(byNewest);

// تفصيل الفئات للطرفين: الصرف والدخل كلّ على حدة
const byCategory = {};
const incomeByCategory = {};
for (const e of monthRows) {
  const bucket = isExp(e) ? byCategory : incomeByCategory;
  bucket[e.category] = (bucket[e.category] || 0) + e.amount;
}

const toList = (obj) => Object.entries(obj)
  .map(([category, amount]) => ({ category, amount: round(amount) }))
  .sort((a, b) => b.amount - a.amount);

// الشهور التي فيها حركات، للتنقّل
const months = [...new Set(live.map((e) => (e.spent_at || '').slice(0, 7)).filter(Boolean))].sort().reverse();

return [{
  json: {
    month,
    months,
    currency: 'SAR',
    entries: monthRows,
    deleted_entries: all.filter((e) => e.deleted && inMonth(e, month)).sort(byNewest),
    totals: {
      today: sum(live.filter((e) => isExp(e) && e.spent_at === todayKey)),
      month: cur.expense,
      income_month: cur.income,
      net_month: cur.net,
      count: cur.count,
      vat_month: round(monthRows.filter(isExp).reduce((s, e) => s + e.vat_amount, 0)),
      balance,
      prev: { expense: prev.expense, income: prev.income, net: prev.net },
      change: { expense: pct(cur.expense, prev.expense), income: pct(cur.income, prev.income) },
      by_category: toList(byCategory),
      income_by_category: toList(incomeByCategory),
    },
  },
}];

const zone = 'Asia/Riyadh';
const body = $('استقبال الطلب').first().json.body ?? {};

const userId = String(body.user_id ?? '').trim();
if (!userId) throw new Error('جلستك انتهت. سجّل دخولك مرة أخرى');

const id = Number(body.id);
if (!Number.isInteger(id) || id <= 0) throw new Error('رقم الحركة غير صالح');

const p = body.patch ?? {};
const out = { id, user_id: userId, edited_at: DateTime.now().setZone(zone).toISO() };

if (p.amount !== undefined) {
  const a = Number(p.amount);
  if (!Number.isFinite(a) || a <= 0) throw new Error('المبلغ لازم يكون رقماً أكبر من صفر');
  out.amount = Math.round(a * 100) / 100;
}

if (p.vat_amount !== undefined) {
  const v = Number(p.vat_amount);
  if (!Number.isFinite(v) || v < 0) throw new Error('مبلغ الضريبة غير صالح');
  if (out.amount !== undefined && v > out.amount) throw new Error('الضريبة ما تصير أكبر من الإجمالي');
  out.vat_amount = Math.round(v * 100) / 100;
}

if (p.direction !== undefined) {
  if (p.direction !== 'expense' && p.direction !== 'income') throw new Error('نوع الحركة غير صالح');
  out.direction = p.direction;
}

if (p.category !== undefined) {
  const allowed = ['مطاعم', 'بقالة', 'قهوة', 'بنزين', 'نقل', 'فواتير', 'إيجار', 'اشتراكات', 'صحة', 'تعليم', 'ترفيه', 'ملابس', 'هدايا', 'ضيافة', 'صيانة', 'رسوم', 'مواد خام', 'راتب', 'مبيعات', 'أخرى'];
  if (!allowed.includes(p.category)) throw new Error('تصنيف غير معروف');
  out.category = p.category;
}

if (p.spent_at !== undefined) {
  const d = DateTime.fromISO(String(p.spent_at), { zone });
  if (!d.isValid) throw new Error('التاريخ غير صالح');
  out.spent_at = d.startOf('day').toISO();
}

if (p.vendor !== undefined) out.vendor = String(p.vendor).trim().slice(0, 120);
if (p.note !== undefined) out.note = String(p.note).trim().slice(0, 300);

if (Object.keys(out).length <= 3) throw new Error('ما فيه أي تعديل مطلوب');

return [{ json: out }];

const zone = 'Asia/Riyadh';
const body = $('استقبال الطلب').first().json.body ?? {};

const userId = String(body.user_id ?? '').trim();
if (!userId) throw new Error('جلستك انتهت. سجّل دخولك مرة أخرى');

const id = Number(body.id);
if (!Number.isInteger(id) || id <= 0) throw new Error('رقم الحركة غير صالح');

const reason = String(body.reason ?? '').trim();
if (reason.length < 3) throw new Error('اكتب سبب الحذف — الدفتر يحتفظ بالسجل ولا يمسحه');
if (reason.length > 200) throw new Error('سبب الحذف طويل. اختصره');

// حذف منطقي فقط: السجل يبقى في الدفتر معلّماً بسببه ووقته
return [{
  json: {
    id,
    user_id: userId,
    deleted: true,
    deleted_at: DateTime.now().setZone(zone).toISO(),
    delete_reason: reason,
  },
}];

// الملكية تُتحقَّق هنا صراحةً، لا عبر شرط تصفية العقدة.
// شرط الحقلين (id + user_id) لم يُطبّق في n8n وسمح لمستخدم
// بتعديل حركة غيره ونسبها لنفسه — مثبَت باختبار فعلي.
const want = $('تحقق التعديل').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r && r.id !== undefined && r.id !== null);
const row = rows.find((r) => Number(r.id) === Number(want.id));

// نفس الرسالة للحالتين حتى لا يُعرَف أي أرقام موجودة
if (!row || String(row.user_id) !== String(want.user_id)) {
  throw new Error('الحركة غير موجودة');
}

return [{ json: want }];

// نفس مبدأ التعديل: الملكية في الكود لا في شرط العقدة.
const want = $('تحقق الحذف').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r && r.id !== undefined && r.id !== null);
const row = rows.find((r) => Number(r.id) === Number(want.id));

if (!row || String(row.user_id) !== String(want.user_id)) {
  throw new Error('الحركة غير موجودة');
}

if (row.deleted === true) {
  throw new Error('هذي الحركة محذوفة أصلاً');
}

return [{ json: want }];
